test('antipsychotic partial has honest boundary, complete source tables and verified correction notes',()=>{
 const s=book.chapters.find(c=>c.number===25).sections[6];assert.equal(s.status,'translated');assert.deepEqual([s.source.pdfStart,s.source.pdfEnd],[709,719]);assert.equal(s.coverage,undefined);const boxes=s.blocks.filter(b=>b.type==='box'),outline=boxes[0];assert.equal(outline.blocks.filter(b=>b.type==='heading').length,9);assert.equal(outline.blocks.filter(b=>b.type==='list').flatMap(b=>b.items).length,14);const tables=s.blocks.filter(b=>b.type==='table');assert.deepEqual(tables.map(t=>[t.headers.length,t.rows.length]),[[5,9],[5,7],[4,9]]);assert.deepEqual(tables[0].rows[0].slice(1,4),['+','+++','+']);assert.deepEqual(tables[0].rows[5].slice(1,4),['+','+++','++']);assert.match(tables[1].rows[3][4],/20–50 мг/);const text=boxes.find(b=>b.title.startsWith('Проверенные уточнения')).blocks.map(StudyModel.blockText).join(' ');for(const t of ['6 часов','25 мг','37,5','12,5','cf377de3','bb34ee82'])assert(text.includes(t),t);assert.equal(s.summary.length,17);assert.equal(s.blocks.at(-1).type,'paragraph');assert(s.blocks.some(b=>b.type==='heading'&&b.text==='Нежелательные эффекты'));const state=StudyModel.emptyState();state.completed[s.id]={revision:3,source:book.source.sha256};state.notes[s.id]='Моя заметка';assert.equal(StudyModel.isRead(s,state,book),false);assert.equal(StudyModel.isPartRead(s,state,book),false);assert.equal(StudyModel.stats(book,state).read,0);assert.equal(StudyModel.stats(book,state).partialRead,0);assert.equal(state.notes[s.id],'Моя заметка');
});
