test('anticholinergic section keeps all six headings, source doses and cognitive risk qualification',()=>{const s=book.chapters.find(c=>c.number===25).sections[7];assert.equal(s.status,'translated');assert.deepEqual([s.source.pdfStart,s.source.pdfEnd],[720,720]);assert.equal(s.blocks.filter(b=>b.type==='heading').length,6);assert.equal(s.summary.length,6);const text=s.blocks.map(StudyModel.blockText).join(' ');for(const t of ['15–20 часов','2–12 мг','5–30 мг','Coupland et al., 2019','не следует назначать рутинно','тепловым ударом','амитриптилина','трижды в день'])assert(text.includes(t),t);assert.match(s.blocks.at(-1).text,/нарушения сна/);assert(!s.blocks.some(b=>b.type==='heading'&&b.text==='Антидепрессанты'));});
